begin;
select no_plan();
insert into auth.users(id,email) values ('aaaa1111-1111-4111-8111-111111111111','billing-a@example.test'),('bbbb2222-2222-4222-8222-222222222222','billing-b@example.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaa1111-1111-4111-8111-111111111111',true);
insert into public.billing_profiles(business_name,business_address,vat_registered,vat_number) values ('Demo Business','Demo business address',true,'DEMO-VAT');
insert into public.clients(id,name,herd_number,county,phone,email) values ('cccc3333-3333-4333-8333-333333333333','Demo Farmer','DEMO-BILL','Cork','0000000000','farmer@example.test');
insert into public.jobs(id,client_id,title) values ('dddd4444-4444-4444-8444-444444444444','cccc3333-3333-4333-8333-333333333333','Demo application preparation');
insert into public.rates(id,name,unit,price_cents) values ('eeee5555-5555-4555-8555-555555555555','Application work','hour',10001);
select throws_ok($$select public.create_invoice_draft('ffff6666-6666-4666-8666-666666666666','dddd4444-4444-4444-8444-444444444444','eeee5555-5555-4555-8555-555555555555',1.25,'Demo customer address',current_date,current_date+30,2300)$$,'23514',null,'unfinished work cannot be billed');
update public.jobs set status='in_progress'; update public.jobs set status='completed';
select lives_ok($$select public.create_invoice_draft('ffff6666-6666-4666-8666-666666666666','dddd4444-4444-4444-8444-444444444444','eeee5555-5555-4555-8555-555555555555',1.25,'Demo customer address',current_date,current_date+30,2300)$$,'draft created');
select is((select net_cents from public.invoices),12501::bigint,'net amount rounded once to cents');
select is((select vat_cents from public.invoices),2875::bigint,'VAT rounded to cents');
select is((select total_cents from public.invoices),15376::bigint,'total exact');
select is((select invoice_number from public.invoices),null::integer,'draft has no issued number');
select lives_ok($$select public.create_invoice_draft('ffff6666-6666-4666-8666-666666666666','dddd4444-4444-4444-8444-444444444444','eeee5555-5555-4555-8555-555555555555',1.25,'Demo customer address',current_date,current_date+30,2300)$$,'exact request replay is safe');
select throws_ok($$select public.create_invoice_draft('ffff6666-6666-4666-8666-666666666666','dddd4444-4444-4444-8444-444444444444','eeee5555-5555-4555-8555-555555555555',2,'Demo customer address',current_date,current_date+30,2300)$$,'23514',null,'replay with changed payload rejected');
select throws_ok($$select public.create_invoice_draft('ffff7777-7777-4777-8777-777777777777','dddd4444-4444-4444-8444-444444444444','eeee5555-5555-4555-8555-555555555555',1,'Demo customer address',current_date,current_date+30,2300)$$,'23505',null,'same job cannot be double billed');
select throws_ok($$update public.invoices set total_cents=1$$,'42501',null,'direct invoice writes denied');
select throws_ok($$update public.jobs set status='in_progress'$$,'23514',null,'billed work cannot be reopened');
select set_config('request.jwt.claim.sub','bbbb2222-2222-4222-8222-222222222222',true);
select is((select count(*)::integer from public.invoices),0,'B cannot read A invoices');
select is((select count(*)::integer from public.billing_profiles),0,'B cannot read A business details');
select throws_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','issue',null)$$,'42501',null,'B cannot issue A invoice');
select throws_ok($$select public.create_invoice_draft('bbbb7777-7777-4777-8777-777777777777','dddd4444-4444-4444-8444-444444444444','eeee5555-5555-4555-8555-555555555555',1,'Demo',current_date,current_date+30,2300)$$,'42501',null,'B cannot bill A job');
select set_config('request.jwt.claim.sub','aaaa1111-1111-4111-8111-111111111111',true);
select lives_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','issue',null)$$,'owner can issue');
select lives_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','issue',null)$$,'issue replay is idempotent');
select is((select invoice_number from public.invoices),1,'issuer has first sequential number');
select is((select count(*)::integer from public.invoice_events where action='issued'),1,'issue recorded once');
update public.billing_profiles set business_name='New business name';
update public.clients set name='New customer name';
select is((select supplier_name from public.invoices),'Demo Business','supplier snapshot preserved');
select is((select customer_name from public.invoices),'Demo Farmer','customer snapshot preserved');
select throws_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','void',null)$$,'23514',null,'issued invoice cannot be discarded');
select lives_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','paid',current_date)$$,'full payment can be recorded');
select lives_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','paid',current_date)$$,'payment replay is idempotent');
select is((select status from public.invoices),'paid','payment status recorded');
select throws_ok($$delete from public.invoices$$,'42501',null,'ordinary invoice deletion denied');
select throws_ok($$delete from public.invoice_events$$,'42501',null,'invoice history protected');
select set_config('request.jwt.claim.sub','bbbb2222-2222-4222-8222-222222222222',true);
insert into public.billing_profiles(business_name,business_address,vat_registered,vat_number) values ('Second Demo Business','Second business address',false,'');
insert into public.clients(id,name,herd_number,county,phone,email) values ('bbbb3333-3333-4333-8333-333333333333','Second Demo Farmer','DEMO-BILL-B','Cork','0000000000','farmer-b@example.test');
insert into public.jobs(id,client_id,title) values ('bbbb4444-4444-4444-8444-444444444444','bbbb3333-3333-4333-8333-333333333333','Second application');
update public.jobs set status='in_progress'; update public.jobs set status='completed';
insert into public.rates(id,name,unit,price_cents) values ('bbbb5555-5555-4555-8555-555555555555','Fixed work','fixed',15000);
select throws_ok($$select public.create_invoice_draft('bbbb6666-6666-4666-8666-666666666666','bbbb4444-4444-4444-8444-444444444444','bbbb5555-5555-4555-8555-555555555555',2,'Demo address',current_date,current_date+30,null)$$,'23514',null,'fixed rate requires one quantity');
select throws_ok($$select public.create_invoice_draft('bbbb6666-6666-4666-8666-666666666666','bbbb4444-4444-4444-8444-444444444444','bbbb5555-5555-4555-8555-555555555555',1,'Demo address',current_date,current_date+30,2300)$$,'23514',null,'unregistered business cannot charge VAT');
select lives_ok($$select public.create_invoice_draft('bbbb6666-6666-4666-8666-666666666666','bbbb4444-4444-4444-8444-444444444444','bbbb5555-5555-4555-8555-555555555555',1,'Demo address',current_date,current_date+30,null)$$,'B can create own invoice');
update public.billing_profiles set business_name='Second Updated Business';
select throws_ok($$select public.transition_invoice('bbbb6666-6666-4666-8666-666666666666','issue',null)$$,'23514',null,'stale business snapshot cannot issue');
select lives_ok($$select public.transition_invoice('bbbb6666-6666-4666-8666-666666666666','void',null)$$,'discard stale draft');
select lives_ok($$select public.create_invoice_draft('bbbb7777-7777-4777-8777-777777777777','bbbb4444-4444-4444-8444-444444444444','bbbb5555-5555-4555-8555-555555555555',1,'Demo address',current_date,current_date+30,null)$$,'discarded work can be billed again');
select lives_ok($$select public.transition_invoice('bbbb7777-7777-4777-8777-777777777777','issue',null)$$,'B can issue own invoice');
select is((select invoice_number from public.invoices where status='issued'),1,'B sequence starts independently at 1');
select is((select supplier_name from public.invoices where status='issued'),'Second Updated Business','B issues under own business name');
select throws_ok($$select * from public.invoice_counters$$,'42501',null,'numbering counter inaccessible to ordinary accounts');
set local role anon;
select throws_ok($$select * from public.invoices$$,'42501',null,'anonymous invoice read denied');
select throws_ok($$select public.transition_invoice('ffff6666-6666-4666-8666-666666666666','issue',null)$$,'42501',null,'anonymous issuing denied');
reset role;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.invoices'::regclass),'invoice RLS forced');
select * from finish(); rollback;
